'use strict';
let thematic='plan';
const originalMap=renderMap,originalDetail=renderDetail,originalRender=render,originalGraveDialog=graveDialog,originalTaskDialog=taskDialog;
const legends={plan:'Flurflächen nach der Planvorlage.',occupancy:'Belegte unter bekannten aktiven Einträgen: grün bis 50 %, gelb bis 80 %, rot über 80 %. Grau: keine bekannten Status. Keine Kapazitätsauslastung.',deadlines:'Rot: Nutzungsende überschritten. Gelb: Nutzungsende innerhalb von 90 Tagen. Grün: spätere Frist. Grau: keine aktive Frist erfasst.',heritage:'Blaugrau: mindestens ein eingetragenes Denkmal-, Ehren- oder Kriegsgrab. Grau: kein solches Merkmal erfasst. Keine amtliche Bestätigung.'};
renderMap=function(){originalMap();fields.forEach(f=>{const p=$(`[data-id="${f.id}"]`),gs=fieldGraves(f.id),s=DFM.summary(gs);let color='';if(thematic==='occupancy')color=s.occupancy===null?'#e2e5e8':s.occupancy<=50?'#c8d9c4':s.occupancy<=80?'#e7d4a3':'#dca99f';if(thematic==='deadlines')color=s.expired?'#dca99f':s.soon?'#e7d4a3':gs.some(g=>DFM.deadline(g)==='later')?'#c8d9c4':'#e2e5e8';if(thematic==='heritage')color=s.heritage?'#aebfcf':'#e2e5e8';p.style.fill=color;p.querySelector('title').textContent=`Fläche ${f.id} · ${gs.length} erfasste Gräber · ${s.expired} Nutzungsenden überschritten · ${s.heritage} Schutzmerkmale`;});$('#themeLegend').textContent=legends[thematic]+(layer!=='work'&&thematic!=='plan'?' Für volle Themenfarben Arbeitskarte wählen.':'');};
$$('[data-theme]').forEach(b=>b.onclick=()=>{thematic=b.dataset.theme;$$('[data-theme]').forEach(x=>x.classList.toggle('active',x===b));if(thematic!=='plan')$('[data-layer="work"]').click();renderMap();});
$$('[data-layer]').forEach(b=>{const old=b.onclick;b.onclick=()=>{old();renderMap();};});
renderDetail=function(){originalDetail();const gs=fieldGraves(selected),s=DFM.summary(gs),section=document.createElement('section');section.className='graveoverview';section.innerHTML=`<div class="sectionmini"><h3>Parzellen im Flur</h3><button id="printField" class="linkbutton">Flurauszug drucken</button></div><p class="micro">${gs.length} erfasst · ${s.counts.Frei} frei · ${s.counts.Belegt} belegt · ${s.expired} Fristen überschritten</p>${gs.length?'<div class="parcel-list">'+gs.map(g=>{const linked=state.tasks.filter(t=>!t.done&&t.graveId===g.id).length;return `<article class="parcel-row"><button class="parcel-main" data-cell="${esc(g.id)}"><strong>${esc(g.number)}</strong><span>${esc(g.name||g.type||'Ohne Bezeichnung')}</span></button><span class="pill ${esc(g.status)}">${esc(g.status)}</span>${linked?`<span class="parcel-task" title="Offene Bauhof-Aufträge">${linked} Auftrag${linked===1?'':'e'}</span>`:''}<button class="parcel-action" data-parcel-task="${esc(g.id)}" aria-label="Arbeitsauftrag für ${esc(g.number)} anlegen">+ Auftrag</button></article>`;}).join('')+'</div>':'<p class="micro">Noch keine Parzellen oder Grabstellen erfasst.</p>'}<p class="micro">Nur erfasste Grabstellen werden angezeigt. Die Reihenfolge bildet keine Lage im Gelände ab.</p>`;$('#detail .detailbody').append(section);$('#printField').onclick=()=>printField();$$('[data-cell]').forEach(b=>b.onclick=()=>graveDialog(b.dataset.cell));$$('[data-parcel-task]').forEach(b=>b.onclick=()=>taskDialog('',b.dataset.parcelTask));};
graveDialog=function(id){originalGraveDialog(id);const g=state.graves.find(g=>g.id===id)||{};const container=document.createElement('div');container.className='formgrid extraform';container.innerHTML=`<label class="formlabel">Geburtsdatum<input type="date" name="birth" value="${esc(g.birth)}"></label><label class="formlabel">Sterbedatum<input type="date" name="death" value="${esc(g.death)}"></label><label class="formlabel">Beisetzungsdatum<input type="date" name="burial" value="${esc(g.burial)}"></label><label class="formlabel">Schutzmerkmal<select name="heritage">${opts(DFM.heritage,g.heritage||'Unbekannt')}</select></label><label class="formlabel full">Quelle / Nachweis zum Merkmal<input name="heritageSource" maxlength="500" value="${esc(g.heritageSource)}" placeholder="z. B. Aktenzeichen oder Bestandsliste"></label><p class="micro full">Nutzungsende und Beisetzungsdatum werden von dir eingegeben. Es werden keine Ruhezeiten automatisch berechnet und keine Meldungen versendet.</p>`;$('#graveForm .formactions').before(container);};
taskDialog=function(id,graveId=''){if(graveId){const grave=state.graves.find(g=>g.id===graveId);if(grave)selected=grave.field;}originalTaskDialog(id);const t=state.tasks.find(t=>t.id===id)||{},field=$('#taskForm [name="field"]').value,graves=fieldGraves(field),container=document.createElement('div');container.className='formgrid';container.innerHTML=`<label class="formlabel">Arbeitsart<select name="workType">${opts(['Kontrolle','Pflege','Verkehrssicherheit','Bestattungsvorbereitung','Instandhaltung','Datenprüfung','Sonstiges'],t.workType||'Kontrolle')}</select></label><label class="formlabel">Grabstelle / Parzelle<select name="graveId"><option value="">Nur Flurbezug</option>${graves.map(g=>`<option value="${esc(g.id)}" ${(t.graveId||graveId)===g.id?'selected':''}>${esc(g.number)}${g.name?' · '+esc(g.name):''}</option>`).join('')}</select></label><label class="formlabel">Zuständig<input name="assignee" maxlength="150" value="${esc(t.assignee)}" placeholder="Team oder Person"></label><label class="formlabel">Bearbeitungsstand<select name="phase">${opts(['Offen','In Arbeit','Erledigt'],t.phase||(t.done?'Erledigt':'Offen'))}</select></label>`;$('#taskForm .formactions').before(container);const fieldSelect=$('#taskForm [name="field"]'),graveSelect=$('#taskForm [name="graveId"]');fieldSelect.onchange=()=>{graveSelect.innerHTML='<option value="">Nur Flurbezug</option>'+fieldGraves(fieldSelect.value).map(g=>`<option value="${esc(g.id)}">${esc(g.number)}${g.name?' · '+esc(g.name):''}</option>`).join('');};};
renderTasks=function(){const rows=state.tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done)).sort((a,b)=>(b.priority==='Hoch')-(a.priority==='Hoch')||(a.due||'9999').localeCompare(b.due||'9999'));$('#taskList').innerHTML=rows.length?rows.map(t=>{const g=state.graves.find(g=>g.id===t.graveId),place=`Flur ${esc(t.field)}${g?' · Grabstelle '+esc(g.number):''}`;return `<article class="taskrow ${t.done?'done':''}"><input type="checkbox" class="taskcheck" data-check="${esc(t.id)}" ${t.done?'checked':''} aria-label="Arbeitsauftrag ${esc(t.title)} als erledigt markieren"><div><div class="worktype">${esc(t.workType||'Allgemeiner Auftrag')}</div><h3>${esc(t.title)}</h3><p>${place}${t.notes?' · '+esc(t.notes):''}</p><p class="taskextra">${esc(t.phase||(t.done?'Erledigt':'Offen'))} · ${esc(t.assignee||'Nicht zugewiesen')}</p></div><div class="taskmeta">${t.priority==='Hoch'?'<span class="urgent">Hohe Priorität</span>':''}<span>${t.due?'Fällig: '+date(t.due):'Ohne Frist'}</span><button class="btn" data-task="${esc(t.id)}">Bearbeiten</button></div></article>`;}).join(''):'<div class="tablecard empty"><span>✓</span><h3>Keine '+(taskFilter==='done'?'erledigten ':taskFilter==='open'?'offenen ':'')+'Arbeitsaufträge.</h3><p>Lege einen Auftrag für Pflege, Kontrolle oder Bestattungsvorbereitung an.</p></div>';$$('[data-check]').forEach(b=>b.onchange=()=>change(s=>{const t=s.tasks.find(t=>t.id===b.dataset.check);t.done=b.checked;t.phase=b.checked?'Erledigt':'Offen';},'Arbeitsauftrag aktualisiert.'));$$('[data-task]').forEach(b=>b.onclick=()=>taskDialog(b.dataset.task));};
$('#newInterment').onclick=()=>{graveDialog();$('#modalTitle').textContent='Beisetzung erfassen';$('#graveForm [name="status"]').value='Belegt';$('#graveForm [name="burial"]').focus();};
$('#recordFilter').onchange=renderGraves;
$('#toggleDetail').onclick=()=>{const collapsed=$('#operations-panel').classList.toggle('collapsed');$('#toggleDetail').setAttribute('aria-expanded',String(!collapsed));};
$('#focusNorth').onclick=()=>{box={x:145,y:45,w:360,h:400};setBox();};
function statCard(label,value,note){return `<article class="analysis-card"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`;}
function renderAnalysis(){const s=DFM.summary(state.graves,state.tasks);const due=state.graves.filter(g=>['expired','soon'].includes(DFM.deadline(g))).sort((a,b)=>a.end.localeCompare(b.end));const withData=fields.filter(f=>fieldGraves(f.id).length);$('#analysisContent').innerHTML=`<div class="analysis-grid">${statCard('Erfasste Gräber',s.total,withData.length+' von '+fields.length+' Flächen mit Einträgen')}${statCard('Belegt unter bekanntem Status',s.occupancy===null?'Keine Daten':s.occupancy+' %',s.counts.Belegt+' von '+s.known+' bekannten aktiven Einträgen')}${statCard('Nutzungsende überschritten',s.expired,s.soon+' weitere innerhalb von 90 Tagen')}${statCard('Schutzmerkmale',s.heritage,'Als Denkmal, Ehren- oder Kriegsgrab erfasst')}</div><div class="analysis-columns"><article class="analysis-panel"><h3>Statusverteilung</h3>${Object.entries(s.counts).map(([k,v])=>`<div class="statusbar"><span>${esc(k)}</span><div><i style="width:${s.total?v/s.total*100:0}%"></i></div><strong>${v}</strong></div>`).join('')}<p class="micro">Belegungsanteil = Belegt / (Frei + Belegt + Reserviert). Unbekannte und aufgelöste Einträge sind aus diesem Anteil ausgeschlossen. Die tatsächliche Gesamtkapazität ist nicht erfasst.</p></article><article class="analysis-panel"><h3>Datenqualität & Aufgaben</h3><p><strong>${s.unknownDates}</strong> aktive Grabeinträge ohne Nutzungsende</p><p><strong>${s.counts.Unbekannt}</strong> Grabeinträge mit unbekanntem Status</p><p><strong>${s.open}</strong> offene Aufgaben, davon <strong>${s.overdue}</strong> überfällig</p><p class="micro">Stichtag: ${date(DFM.today())}. Überschrittene Fristen lösen keine automatische Freigabe eines Grabes aus.</p></article></div><article class="tablecard"><div class="mapheading"><h2>Fristen im Blick</h2><span>${due.length} Einträge</span></div><div class="tablewrap"><table><thead><tr><th>Fläche / Grab</th><th>Name</th><th>Nutzungsende</th><th>Einordnung</th><th>Aktion</th></tr></thead><tbody>${due.map(g=>`<tr><td>${esc(g.field)} / ${esc(g.number)}</td><td>${esc(g.name)||'Nicht angegeben'}</td><td>${date(g.end)}</td><td>${DFM.deadline(g)==='expired'?'Überschritten':'In '+DFM.days(g.end)+' Tagen'}</td><td><button data-due="${esc(g.id)}">Bearbeiten</button></td></tr>`).join('')}</tbody></table></div>${due.length?'':'<p class="empty">Keine entsprechenden Fristen erfasst.</p>'}</article>`;$$('[data-due]').forEach(b=>b.onclick=()=>graveDialog(b.dataset.due));}
render=function(){originalRender();renderAnalysis();};
function reportTable(gs){return `<table><thead><tr><th>Fläche / Grab</th><th>Name</th><th>Status</th><th>Nutzungsende</th><th>Schutzmerkmal</th></tr></thead><tbody>${gs.map(g=>`<tr><td>${esc(g.field)} / ${esc(g.number)}</td><td>${esc(g.name)}</td><td>${esc(g.status)}</td><td>${date(g.end)}</td><td>${esc(g.heritage||'Unbekannt')}</td></tr>`).join('')}</tbody></table>`;}
function printDocument(title,html){$('#printReport').innerHTML=`<h1>DigiFried-Management-Melaten</h1><h2>${esc(title)}</h2><p>Stand: ${date(DFM.today())} · Lokaler Arbeitsstand</p>${html}<p class="reportfoot">Schematischer Arbeitsplan, kein amtlicher Katasterauszug. Angaben stammen aus lokalen Einträgen. Flächen sind nicht georeferenziert. Schutzmerkmale sind manuelle Angaben.</p>`;window.print();}
function printField(){const f=fields.find(f=>f.id===selected),v=state.fields[selected]||{};printDocument('Flächenauszug '+selected,`<p>Bereich: ${esc(f.zone)} · Prüfstatus: ${esc(v.condition||'Ungeprüft')}</p><p class="preserve">${esc(v.notes||'Keine Flächennotizen.')}</p><h3>Erfasste Gräber</h3>${reportTable(fieldGraves(selected))}<h3>Offene Aufgaben</h3><ul>${fieldTasks(selected).map(t=>`<li>${esc(t.title)} · ${esc(t.assignee||'Nicht zugewiesen')} · ${date(t.due)}</li>`).join('')||'<li>Keine offenen Aufgaben</li>'}</ul>`);}
$('#printOverview').onclick=()=>{const s=DFM.summary(state.graves,state.tasks);printDocument('Bestand & Fristen',`<p>${s.total} erfasste Gräber · ${s.counts.Frei} frei · ${s.counts.Belegt} belegt · ${s.open} offene Aufgaben</p><p>${s.expired} Nutzungsenden überschritten · ${s.soon} innerhalb von 90 Tagen</p>${reportTable(state.graves)}`);};
render();
